namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CourseCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and civilizations." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor", Bio = "Pioneer in computing theory with 20 years of teaching experience. Research interests include algorithm design and computational complexity.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor", Bio = "Expert in artificial intelligence and machine learning. Published over 50 peer-reviewed papers.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor", Bio = "Renowned mathematician specializing in abstract algebra and theoretical physics. Award-winning educator.", Email = "enoether@university.edu" },
            new() { Id = 4, Name = "Dr. William Shakespeare", Title = "Professor Emeritus", Bio = "Literary scholar with expertise in Renaissance literature and creative writing. Author of multiple textbooks.", Email = "wshakespeare@university.edu" },
            new() { Id = 5, Name = "Dr. Marie Curie", Title = "Professor", Bio = "Groundbreaking researcher in radioactivity and nuclear physics. Mentor to dozens of graduate students.", Email = "mcurie@university.edu" },
            new() { Id = 6, Name = "Dr. Herodotus Crane", Title = "Associate Professor", Bio = "Historian focusing on ancient civilizations and cultural exchange. Leads the university's archaeology program.", Email = "hcrane@university.edu" },
            new() { Id = 7, Name = "Dr. Rosalind Franklin", Title = "Professor", Bio = "Molecular biologist known for contributions to understanding DNA structure. Active research lab with 15 members.", Email = "rfranklin@university.edu" },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering the fundamentals of programming, data structures, and algorithmic thinking. Students will learn Python and build several projects.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "In-depth study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", Location = "Science Hall 305", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[0], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 450", Title = "Artificial Intelligence", Description = "Survey of AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks. Includes hands-on projects with real-world datasets.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", DepartmentId = 1, Department = _departments[0], Instructor = _instructors[1], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH 201", Title = "Calculus II", Description = "Continuation of single-variable calculus covering techniques of integration, sequences, series, and introduction to multivariable calculus.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Building 101", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 5, Code = "MATH 310", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of differential equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 203", DepartmentId = 2, Department = _departments[1], Instructor = _instructors[2], IsFeatured = true, MaxEnrollment = 50, CurrentEnrollment = 38 },
            new() { Id = 6, Code = "ENG 101", Title = "English Composition", Description = "Development of writing skills through analysis of texts and practice in various modes of composition including narrative, analytical, and argumentative essays.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities Hall 120", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 7, Code = "ENG 350", Title = "Shakespeare and Renaissance Literature", Description = "Critical study of Shakespeare's major plays and poetry in the context of Renaissance literary and cultural movements.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities Hall 210", DepartmentId = 3, Department = _departments[2], Instructor = _instructors[3], IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 22 },
            new() { Id = 8, Code = "PHYS 201", Title = "General Physics I", Description = "Calculus-based introduction to mechanics, thermodynamics, and waves. Laboratory component included with weekly experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:50 PM", Location = "Physics Building 100", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 52 },
            new() { Id = 9, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, Schrödinger equation, hydrogen atom, and applications to modern physics.", Credits = 3, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Physics Building 301", DepartmentId = 4, Department = _departments[3], Instructor = _instructors[4], IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 18 },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Liberal Arts 150", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 67 },
            new() { Id = 11, Code = "HIST 320", Title = "The Ancient World", Description = "In-depth study of ancient Mesopotamia, Egypt, Greece, and Rome. Examines political systems, daily life, art, and philosophy.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Liberal Arts 220", DepartmentId = 5, Department = _departments[4], Instructor = _instructors[5], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 31 },
            new() { Id = 12, Code = "BIO 101", Title = "Introduction to Biology", Description = "Foundational course covering cell biology, genetics, evolution, and ecology. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 1:00–3:50 PM", Location = "Life Sciences 100", DepartmentId = 6, Department = _departments[5], Instructor = _instructors[6], IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 89 },
            new() { Id = 13, Code = "BIO 340", Title = "Molecular Biology", Description = "Advanced study of molecular mechanisms in biological systems including DNA replication, transcription, translation, and gene regulation.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Life Sciences 310", DepartmentId = 6, Department = _departments[5], Instructor = _instructors[6], IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 29 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        var course = GetCourse(request.CourseId);
        if (course is null || course.CurrentEnrollment >= course.MaxEnrollment)
            return false;

        course.CurrentEnrollment++;
        return true;
    }
}

