arguments.file_text:
@page "/courses"
@rendermode InteractiveServer
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name (@dept.Code)</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
    </div>
</div>

@if (filteredCourses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <p class="text-body-secondary mb-3">Showing @filteredCourses.Count course(s)</p>
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Schedule</th>
                    <th>Enrollment</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in filteredCourses)
                {
                    <tr>
                        <td>@course.Code</td>
                        <td>@course.Title</td>
                        <td>@course.Department.Name</td>
                        <td>@course.Credits</td>
                        <td>@course.Instructor.Name</td>
                        <td><small>@course.Schedule</small></td>
                        <td>
                            <span class="badge @(course.CurrentEnrollment >= course.MaxEnrollment ? "bg-danger" : "bg-success")">
                                @course.CurrentEnrollment / @course.MaxEnrollment
                            </span>
                        </td>
                        <td>
                            <a href="courses/@course.Id" class="btn btn-sm btn-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<UniversityCourseCatalog.Models.Department> departments = new();
    private List<UniversityCourseCatalog.Models.Course> filteredCourses = new();

    private string _searchTerm = string.Empty;
    private string searchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; FilterCourses(); }
    }

    private int _selectedDepartmentId;
    private int selectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; FilterCourses(); }
    }

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();

        var uri = new Uri(Navigation.Uri);
        var query = System.Web.HttpUtility.ParseQueryString(uri.Query);
        if (int.TryParse(query["departmentId"], out var deptId))
        {
            _selectedDepartmentId = deptId;
        }

        FilterCourses();
    }

    private void FilterCourses()
    {
        filteredCourses = CatalogService.SearchCourses(
            string.IsNullOrWhiteSpace(searchTerm) ? null : searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        FilterCourses();
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CourseCatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request for a course. All fields are required.</p>

@if (submitted)
{
    @if (success)
    {
        <div class="alert alert-success">
            <h4>Enrollment Request Submitted</h4>
            <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
                <strong>@selectedCourseTitle</strong> has been received.</p>
            <a href="courses" class="btn btn-primary">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="alert alert-danger">
            <h4>Enrollment Failed</h4>
            <p>The course may be full or invalid. Please try another course.</p>
            <button type="button" class="btn btn-outline-primary" @onclick="Reset">Try Again</button>
        </div>
    }
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <form method="post" @onsubmit="HandleSubmit" @formname="enrollment-form">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                           value="@Model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                           value="@Model.StudentId" required placeholder="e.g., S12345678" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="Model.CourseId" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            @if (course.Id == Model.CourseId)
                            {
                                <option value="@course.Id" selected>@course.Code — @course.Title (@course.CurrentEnrollment/@course.MaxEnrollment enrolled)</option>
                            }
                            else
                            {
                                <option value="@course.Id">@course.Code — @course.Title (@course.CurrentEnrollment/@course.MaxEnrollment enrolled)</option>
                            }
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = new();
    private bool submitted;
    private bool success;
    private string selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";
        success = CatalogService.SubmitEnrollmentRequest(Model);
        submitted = true;
    }

    private void Reset()
    {
        submitted = false;
        success = false;
        Model = new();
    }
}

